            h('button',{className:'dsbw-skin','aria-label':'选择鲸鱼娘形象','aria-pressed':skin==='whalechan',onClick:()=>chooseSkin('whalechan')},h('img',{src:GIRL_ASSET,alt:'',draggable:false}),'鲸鱼娘 · 抱饭碗')
