          h('details',{className:'dsbw-preview'},h('summary',null,'预览动作'),h('div',{className:'dsbw-preview-actions'},...Object.entries(PHASES).map(([value,label])=>h('button',{key:value,onClick:()=>previewAction(value),'aria-label':`预览${label}动画`},label)),h('button',{onClick:()=>setPreview(null)},'恢复实际状态')))
